package com.example.moviebooking.booking;
import com.example.moviebooking.auth.entity.User;
import com.example.moviebooking.auth.repository.UserRepository;
import com.example.moviebooking.catalog.MovieRepository;
import com.example.moviebooking.common.exception.ApiException;
import com.example.moviebooking.notification.NotificationService;
import com.example.moviebooking.payment.*;
import com.example.moviebooking.showtime.*;
import com.example.moviebooking.venue.*;
import org.springframework.stereotype.Service;
import org.springframework.data.domain.Sort;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.scheduling.annotation.Scheduled;
import java.security.Principal;
import java.time.Instant;
import java.util.*;
@Service public class BookingService {
 private final BookingRepository bookings; private final ShowRepository shows; private final SeatRepository seats; private final MovieRepository movies; private final TheatreRepository theatres; private final ScreenRepository screens; private final UserRepository users; private final PaymentRepository payments; private final NotificationService notifications;
 private final LayoutSeatRepository layoutSeats; private final LayoutVersionRepository layoutVersions; private final SeatHoldRepository holds; private final WaitingListRepository waiting; @Value("${booking.seat-hold-minutes:5}") private long holdMinutes; @Value("${booking.waiting-list-offer-minutes:5}") private long offerMinutes;
 public BookingService(BookingRepository bookings,ShowRepository shows,SeatRepository seats,MovieRepository movies,TheatreRepository theatres,ScreenRepository screens,UserRepository users,PaymentRepository payments,NotificationService notifications,LayoutSeatRepository layoutSeats,LayoutVersionRepository layoutVersions,SeatHoldRepository holds,WaitingListRepository waiting){this.bookings=bookings;this.shows=shows;this.seats=seats;this.movies=movies;this.theatres=theatres;this.screens=screens;this.users=users;this.payments=payments;this.notifications=notifications;this.layoutSeats=layoutSeats;this.layoutVersions=layoutVersions;this.holds=holds;this.waiting=waiting;}
 @Transactional public List<SeatHold> hold(Principal p,SeatHoldRequest r){users.findById(p.getName()).orElseThrow(()->new ApiException(401,"UNAUTHORIZED","Authentication required"));var show=shows.findById(r.showId).orElseThrow(()->new ApiException(404,"SHOW_NOT_FOUND","Show not found"));if(show.status!=ShowStatus.OPEN)throw new ApiException(400,"SHOW_CLOSED","Show is not open for booking");expireHolds();var requested=new LinkedHashSet<>(r.seatIds);holds.deleteOld(show.id,requested,SeatHoldStatus.EXPIRED);if(requested.size()!=r.seatIds.size())throw new ApiException(400,"DUPLICATE_SEAT","Seat selected more than once");var validSeatIds=seats.findByScreenId(show.screenId).stream().filter(s->!s.disabled).map(s->s.id).collect(java.util.stream.Collectors.toSet());if(requested.stream().anyMatch(s->!validSeatIds.contains(s)))throw new ApiException(400,"INVALID_SEAT","One or more selected seats do not exist");var now=Instant.now();var active=holds.findByShowIdAndStatusAndExpiresAtAfter(show.id,SeatHoldStatus.ACTIVE,now);var booked=bookings.findBookedSeatIds(show.id,List.of(BookingStatus.PENDING,BookingStatus.CONFIRMED));var held=active.stream().filter(h->!h.userId.equals(p.getName())).map(h->h.seatId).toList();if(requested.stream().anyMatch(s->booked.contains(s)||held.contains(s)))throw new ApiException(409,"SEAT_UNAVAILABLE","One or more seats are currently unavailable");var expiry=now.plusSeconds(Math.max(1,show.holdMinutes)*60);var out=new ArrayList<>(active.stream().filter(h->h.userId.equals(p.getName())&&requested.contains(h.seatId)).toList());for(String seat:requested){if(out.stream().anyMatch(h->h.seatId.equals(seat)))continue;var h=new SeatHold();h.showId=show.id;h.seatId=seat;h.userId=p.getName();h.expiresAt=expiry;out.add(holds.save(h));}return out;}
 public List<SeatHold> activeHolds(Principal p,String showId){expireHolds();return holds.findByUserIdAndStatusAndExpiresAtAfter(p.getName(),SeatHoldStatus.ACTIVE,Instant.now()).stream().filter(h->h.showId.equals(showId)).toList();}
 @Scheduled(fixedDelay=30000) @Transactional public void expireHolds(){var now=Instant.now();holds.expired(SeatHoldStatus.ACTIVE,now).forEach(h->h.status=SeatHoldStatus.EXPIRED);}
 public List<Booking> mine(Principal p){return bookings.findByUserIdOrderByCreatedAtDesc(p.getName());}
 public List<Booking> all(){return bookings.findAll(Sort.by(Sort.Direction.DESC,"createdAt"));}
 public Booking get(String id,Principal p){var b=bookings.findById(id).orElseThrow(()->new ApiException(404,"BOOKING_NOT_FOUND","Booking not found"));if(!b.userId.equals(p.getName()))throw new ApiException(403,"FORBIDDEN","Access denied");return b;}
 @Transactional public Booking create(Principal p,CreateBookingRequest r){User u=users.findById(p.getName()).orElseThrow(()->new ApiException(401,"UNAUTHORIZED","Authentication required"));var show=shows.findById(r.showId).orElseThrow(()->new ApiException(404,"SHOW_NOT_FOUND","Show not found"));if(show.status!=ShowStatus.OPEN)throw new ApiException(400,"SHOW_CLOSED","Show is not open for booking");var now=Instant.now();if(show.bookingOpens!=null&&now.isBefore(show.bookingOpens))throw new ApiException(400,"BOOKING_NOT_OPEN","Booking has not opened");if(show.bookingCloses!=null&&now.isAfter(show.bookingCloses))throw new ApiException(400,"BOOKING_CLOSED","Booking is closed");var requested=new ArrayList<>(new LinkedHashSet<>(r.seatIds));if(requested.size()!=r.seatIds.size())throw new ApiException(400,"DUPLICATE_SEAT","Seat selected more than once");var existing=bookings.activeByMobile(show.id,u.mobile,List.of(BookingStatus.PENDING,BookingStatus.CONFIRMED)).stream().mapToInt(b->b.ticketCount).sum();if(existing+requested.size()>show.maxTicketsPerMobile)throw new ApiException(400,"TICKET_LIMIT","Ticket limit exceeded for this mobile number");var screen=screens.findById(show.screenId).orElseThrow(()->new ApiException(404,"SCREEN_NOT_FOUND","Screen not found"));var valid=show.layoutVersionId==null?List.<LayoutSeat>of():layoutSeats.findByLayoutVersionIdAndIdIn(show.layoutVersionId,requested);if(valid.isEmpty()&&show.layoutVersionId!=null){var legacy=screen.seats.stream().filter(seat->requested.contains(seat.id)).toList();if(legacy.size()==requested.size())valid=legacy.stream().map(seat->{var x=new LayoutSeat();x.id=seat.id;x.label=seat.label;x.disabled=seat.disabled;return x;}).toList();}if(valid.size()!=requested.size()||valid.stream().anyMatch(s->s.disabled))throw new ApiException(400,"INVALID_SEAT","One or more seats are invalid or unavailable for this show layout");if(bookings.anySeatBooked(show.id,requested,List.of(BookingStatus.PENDING,BookingStatus.CONFIRMED)))throw new ApiException(409,"SEAT_ALREADY_BOOKED","One or more seats are already booked");var movie=movies.findById(show.movieId).orElseThrow();var theatre=theatres.findById(show.theatreId).orElseThrow();var bookingScreen=screen;var b=new Booking();b.userId=u.id;b.showId=show.id;b.seatIds=requested;b.ticketCount=requested.size();b.totalAmount=show.ticketPrice.multiply(java.math.BigDecimal.valueOf(requested.size()));b.status=show.ticketType==TicketType.FREE&&!show.requireAdminConfirmation?BookingStatus.CONFIRMED:BookingStatus.PENDING;b.confirmationStatus=show.requireAdminConfirmation?ConfirmationStatus.PENDING:ConfirmationStatus.AUTO;b.movie=movie.title;b.theatre=theatre.name;b.screen=bookingScreen.name;b.date=show.date.toString();b.time=show.startTime.toString();b.mobile=u.mobile;b.email=u.email;b.notification=notifications.record(u.id,"BOOKING_CREATED","Booking "+b.status.name().toLowerCase()+" for "+movie.title);bookings.save(b);holds.findByUserIdAndStatusAndExpiresAtAfter(u.id,SeatHoldStatus.ACTIVE,Instant.now()).stream().filter(h->h.showId.equals(show.id)&&requested.contains(h.seatId)).forEach(h->h.status=SeatHoldStatus.CONVERTED);var pay=new Payment();pay.bookingId=b.id;pay.amount=b.totalAmount;pay.status=show.ticketType==TicketType.FREE?PaymentStatus.NOT_REQUIRED:PaymentStatus.PENDING;payments.save(pay);notifications.sendTicket(u,b,movie.posterUrl);return b;}
 @Transactional public Booking cancel(String id,Principal p,List<String> seatsToCancel){var b=get(id,p);if(b.status==BookingStatus.CANCELLED)return b;if(b.seatIds.size()>1&&(seatsToCancel==null||seatsToCancel.isEmpty()))throw new ApiException(400,"SEATS_REQUIRED","Choose which seats to cancel");var selected=seatsToCancel==null||seatsToCancel.isEmpty()?new ArrayList<>(b.seatIds):new ArrayList<>(seatsToCancel);if(selected.isEmpty()||new HashSet<>(selected).size()!=selected.size())throw new ApiException(400,"INVALID_SEAT","Choose each seat only once");if(!b.seatIds.containsAll(selected))throw new ApiException(400,"INVALID_SEAT","Selected seat is not part of this booking");int previousCount=b.ticketCount;var perTicket=b.totalAmount.divide(java.math.BigDecimal.valueOf(previousCount),2,java.math.RoundingMode.HALF_UP);b.seatIds.removeAll(selected);b.ticketCount=b.seatIds.size();b.totalAmount=b.totalAmount.subtract(perTicket.multiply(java.math.BigDecimal.valueOf(selected.size())));if(b.ticketCount==0)b.status=BookingStatus.CANCELLED;b.notification=notifications.record(b.userId,"BOOKING_CANCELLED",selected.size()==1?"Seat "+selected.get(0)+" cancelled for "+b.movie:"Seats "+String.join(", ",selected)+" cancelled for "+b.movie);emailBookingUpdate(b);offerNext(b.showId,b.movie);return b;}
 @Transactional public Booking adminConfirm(String id){var b=bookings.findById(id).orElseThrow(()->new ApiException(404,"BOOKING_NOT_FOUND","Booking not found"));b.status=BookingStatus.CONFIRMED;b.confirmationStatus=ConfirmationStatus.CONFIRMED;b.notification=notifications.record(b.userId,"BOOKING_CONFIRMED","Booking confirmed for "+b.movie);emailBookingUpdate(b);return b;}
 @Transactional public Booking adminCancel(String id,String reason,List<String> seatsToCancel){var b=bookings.findById(id).orElseThrow(()->new ApiException(404,"BOOKING_NOT_FOUND","Booking not found"));if(b.status!=BookingStatus.CANCELLED){var selected=seatsToCancel==null||seatsToCancel.isEmpty()?new ArrayList<>(b.seatIds):new ArrayList<>(seatsToCancel);if(!b.seatIds.containsAll(selected))throw new ApiException(400,"INVALID_SEAT","Selected seat is not part of this booking");b.seatIds.removeAll(selected);b.ticketCount=b.seatIds.size();if(b.ticketCount==0)b.status=BookingStatus.CANCELLED;b.cancellationReason=reason.trim();b.notification=notifications.record(b.userId,"BOOKING_CANCELLED","Seats "+String.join(", ",selected)+" cancelled for "+b.movie+": "+b.cancellationReason);emailBookingUpdate(b);offerNext(b.showId,b.movie);}return b;}
 private void offerNext(String showId,String movie){int available=availableSeatCount(showId);waiting.findByShowIdAndStatusOrderByPositionAscCreatedAtAsc(showId,WaitingListStatus.WAITING).stream().filter(e->e.requestedSeatsCount<=available).findFirst().ifPresent(e->{e.status=WaitingListStatus.OFFERED;e.offerExpiresAt=Instant.now().plusSeconds(offerMinutes*60);String message=e.requestedSeatsCount+" seat(s) are available for "+movie+". Complete your booking before the offer expires.";notifications.record(e.userId,"WAITING_LIST_OFFER",message);String poster=shows.findById(showId).flatMap(show->movies.findById(show.movieId)).map(item->item.posterUrl).orElse(null);notifications.sendUserMessage(e.userId,"WAITING_LIST_OFFER","Tickets are available for "+movie,message,poster);});}
 private void emailBookingUpdate(Booking booking){users.findById(booking.userId).filter(user->user.email!=null&&!user.email.isBlank()).ifPresent(user->{String poster=shows.findById(booking.showId).flatMap(show->movies.findById(show.movieId)).map(movie->movie.posterUrl).orElse(null);notifications.sendTicket(user,booking,poster);});}
 private int availableSeatCount(String showId){var show=shows.findById(showId).orElse(null);if(show==null)return 0;var unavailable=new HashSet<>(bookings.findBookedSeatIds(showId,List.of(BookingStatus.PENDING,BookingStatus.CONFIRMED)));unavailable.addAll(holds.findByShowIdAndStatusAndExpiresAtAfter(showId,SeatHoldStatus.ACTIVE,Instant.now()).stream().map(h->h.seatId).toList());if(show.layoutVersionId!=null){return (int)layoutSeats.findByLayoutVersionIdOrderByRowNumberAscColumnNumberAsc(show.layoutVersionId).stream().filter(seat->!seat.disabled&&!unavailable.contains(seat.id)).count();}return screens.findById(show.screenId).map(screen->(int)screen.seats.stream().filter(seat->!seat.disabled&&!unavailable.contains(seat.id)).count()).orElse(0);}
 @Transactional public Booking markAttended(String id,boolean attended){var b=bookings.findById(id).orElseThrow(()->new ApiException(404,"BOOKING_NOT_FOUND","Booking not found"));b.attended=attended;return b;}
}




